ops:
  recStageFromDrive: [apiRecStageFromDrive, ['系統維護']],

/** 從雲端資料夾收集紀錄表到暫存區（限系統擁有者；後台需「唯讀雲端硬碟」權限）
 *  args = { folderId, path }：回傳子資料夾清單（由前台逐一呼叫）並把本層的 .doc/.docx/.odt/.pdf 複製到暫存區
 *  照片資料夾（PIC、照片）與 desktop.ini 等略過；同一來源檔案已收集過就不重複 */
function apiRecStageFromDrive(args, user) {
  if (String(user.Email).toLowerCase() !== String(prop_('OWNER_EMAIL', DEFAULT_OWNER)).toLowerCase()) throw new Error('限系統擁有者');
  const fid = String(args.folderId || ''), path = String(args.path || '');
  if (!/^[\w-]{10,}$/.test(fid)) throw new Error('資料夾 ID 不正確');
  const items = [];
  let token = '';
  do {
    const q = encodeURIComponent("'" + fid + "' in parents and trashed=false");
    const r = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files?q=' + q + '&fields=nextPageToken,files(id,name,mimeType,size)&pageSize=1000&supportsAllDrives=true&includeItemsFromAllDrives=true' + (token ? '&pageToken=' + token : '')).getContentText());
    (r.files || []).forEach(f => items.push(f)); token = r.nextPageToken || '';
  } while (token);
  const folders = items.filter(f => f.mimeType === 'application/vnd.google-apps.folder' && !/^(PIC|照片|相片|photo)/i.test(f.name))
    .map(f => ({ id: f.id, name: f.name, path: path ? path + '/' + f.name : f.name }));
  const docs = items.filter(f => /\.(docx?|odt|pdf)$/i.test(f.name));
  const have = {}; readTable_('紀錄匯入').forEach(r => { const m = String(r.來源 || '').match(/^drive:([\w-]+)/); if (m) have[m[1]] = 1; });
  let staged = 0, skipped = 0; const rows = [];
  docs.forEach(f => {
    if (have[f.id]) { skipped++; return; }
    const cp = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + f.id + '/copy?fields=id,size&supportsAllDrives=true', {
      method: 'post', contentType: 'application/json', payload: JSON.stringify({ name: f.name, parents: [stageFolder_()] }) }).getContentText());
    rows.push({ 檔案ID: cp.id, 原檔名: f.name, 類型: f.mimeType, 大小: +(cp.size || f.size || 0), 來源: ('drive:' + f.id + ' ' + (path ? path + '/' : '') + f.name).slice(0, 300), 匯入者: user.Email, 匯入時間: nowStr_(), 狀態: '待對應', 案件編號: '', 說明: '' });
    staged++;
  });
  if (rows.length) appendRows_('紀錄匯入', rows);
  return { folders: folders, staged: staged, skipped: skipped, others: items.length - folders.length - docs.length };
}
